const brandingData = $('Obtener Branding').first().json || {};
const demoData = $('Obtener Datos Estética').first().json || {};

const turnosItems = demoData.turnos || [];
const serviciosItems = demoData.servicios || [];
const staffItems = demoData.staff || [];

// Fecha del reporte: si se pasa ?fecha=YYYY-MM-DD en el webhook se usa esa.
// De lo contrario, si se ejecuta entre 00:00 y 05:00 de la madrugada (hora Argentina),
// corresponde al cierre del día anterior. En cualquier otro momento (ej. cron 21:00 hs), al día de hoy.
let fechaParam = null;
try {
  const trig = $('Webhook Disparador Manual').first()?.json;
  fechaParam = trig?.query?.fecha || trig?.body?.fecha;
} catch (e) {}

const ahora = new Date();
const artTime = new Date(ahora.getTime() - 3 * 3600 * 1000);
const artHour = artTime.getUTCHours();

let targetDate = artTime;
if (artHour < 5) {
  targetDate = new Date(artTime.getTime() - 24 * 3600 * 1000);
}
const fechaHoy = (fechaParam && /^\d{4}-\d{2}-\d{2}$/.test(fechaParam.toString().trim()))
  ? fechaParam.toString().trim()
  : targetDate.toISOString().split('T')[0];

// Mapeos de nombres y precios
const preciosMap = {};
serviciosItems.forEach(s => {
  const item = s.json || s;
  const rawCost = item.Costo !== undefined ? item.Costo : 0;
  const num = parseInt(rawCost.toString().replace(/[^0-9]/g, ''), 10) || 0;
  if (item.ID_Servicio) preciosMap[item.ID_Servicio.toString().trim().toLowerCase()] = num;
  if (item.Nombre_Servicio) preciosMap[item.Nombre_Servicio.toString().trim().toLowerCase()] = num;
});

const staffMap = {};
staffItems.forEach(st => {
  const item = st.json || st;
  if (item.ID_Staff) staffMap[item.ID_Staff.toString().trim()] = item.Nombre;
});

// Filtrar turnos del día
const turnosHoy = turnosItems.filter(t => {
  const item = t.json || t;
  const f = (item.Fecha || item.fecha || '').toString().trim();
  return f === fechaHoy;
});

let totalTurnos = turnosHoy.length;
let facturacionTotal = 0;
let confirmados = 0;
let agendados = 0;
let cancelados = 0;

const staffBreakdown = {};
const serviciosCount = {};

turnosHoy.forEach(t => {
  const item = t.json || t;
  const estado = (item.Estado || item.estado || 'Agendado').toString().trim();
  const rawSvc = (item.ID_Servicio || item.Servicio || '').toString().trim();
  const rawStaffId = (item.ID_Staff || '').toString().trim();
  const staffName = staffMap[rawStaffId] || item.Staff || rawStaffId || 'Sin asignar';

  const costo = preciosMap[rawSvc.toLowerCase()] || 0;

  if (estado.toLowerCase() === 'cancelado') {
    cancelados++;
  } else {
    facturacionTotal += costo;
    if (estado.toLowerCase().includes('confirmado')) {
      confirmados++;
    } else {
      agendados++;
    }

    // Por profesional
    if (!staffBreakdown[staffName]) staffBreakdown[staffName] = { turnos: 0, total: 0 };
    staffBreakdown[staffName].turnos++;
    staffBreakdown[staffName].total += costo;

    // Por servicio
    serviciosCount[rawSvc] = (serviciosCount[rawSvc] || 0) + 1;
  }
});

// Servicio más solicitado
let topServicio = "Ninguno";
let maxSvcCount = 0;
for (const [sName, sCount] of Object.entries(serviciosCount)) {
  if (sCount > maxSvcCount) {
    maxSvcCount = sCount;
    topServicio = sName + ' (' + sCount + ')';
  }
}

// Destinatario del correo
const ownerEmail = (brandingData.ownerEmail && brandingData.ownerEmail.trim().length > 3)
  ? brandingData.ownerEmail.trim()
  : 'espositosabrina29@gmail.com';

const brandName = brandingData.name || 'Lumina Estética';
const facturacionFmt = '$' + facturacionTotal.toLocaleString('de-DE');

return [{
  json: {
    fechaHoy,
    totalTurnos,
    facturacionTotal,
    facturacionFmt,
    confirmados,
    agendados,
    cancelados,
    turnosEfectivos: confirmados + agendados,
    topServicio,
    staffBreakdown,
    ownerEmail,
    brandName,
    brandingData,
    turnosDetalle: turnosHoy.map(t => {
      const item = t.json || t;
      return {
        hora: item.Hora_Inicio || '',
        cliente: item.Nombre_Completo || item.Cliente || 'Cliente',
        servicio: item.ID_Servicio || '',
        staff: staffMap[item.ID_Staff] || item.ID_Staff || '',
        estado: item.Estado || 'Agendado',
        monto: '$' + ((preciosMap[(item.ID_Servicio || '').toLowerCase()] || 0).toLocaleString('de-DE'))
      };
    })
  }
}];
